  const assignmentFor = id => catalog()?.assignments.find(row=>String(row.templateId)===String(id)) || {templateId:String(id),categoryId:catalog()?.defaultCategoryId,version:0};
  const categoryFor = id => catalog()?.categories.find(row=>row.id===assignmentFor(id).categoryId);
