    const table=host.querySelector('.fm-table'),layout=document.createElement('div'),list=document.createElement('div'),panel=document.createElement('aside');layout.className='fm-review-layout';list.className='fm-review-list';panel.id='fm-review-panel';panel.className='fm-review-panel';panel.setAttribute('aria-label','Selected monthly payment');table.before(layout);list.append(table);layout.append(list,panel);table.querySelector('thead').innerHTML='<tr><th>PAYMENT / CATEGORY</th><th>AMOUNT / STATUS</th><th>ACTIONS</th></tr>';
